$errors=[Collections.Generic.List[string]]::new()
function Add-Error($message){$errors.Add([string]$message)}
function Eq($name,$actual,$expected){if($actual-ne$expected){Add-Error "$name expected=$expected actual=$actual"}}
function Seq($name,$actual,$expected){$a=if($null-eq$actual){@()}else{@($actual)};$e=if($null-eq$expected){@()}else{@($expected)};if(($a|ConvertTo-Json -Compress -Depth 30)-ne($e|ConvertTo-Json -Compress -Depth 30)){Add-Error "$name sequence mismatch"}}
function Exact-Keys($name,$object,$expected){Seq "$name keys" @($object.PSObject.Properties.Name|Sort-Object) @($expected|Sort-Object)}
function Load($path){Get-Content -LiteralPath $path -Raw -Encoding UTF8|ConvertFrom-Json}
