function Bound($name){$entry=$contract.boundArtifacts.$name;if($null-eq$entry){Add-Error "missing artifact $name";return};Exact-Keys "artifact $name" $entry @('path','sha256');Eq "$name declared" ([string]$entry.sha256).ToUpperInvariant() $hashes[$name];$path=Join-Path $repo ([string]$entry.path);if(-not(Test-Path -LiteralPath $path)){Add-Error "missing file $name";return};Eq "$name actual" (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash $hashes[$name];if([IO.Path]::GetExtension($path)-eq'.json'){$loaded[$name]=Load $path}}
