 if($loaded.ContainsKey('stageGateContract')){$s=$loaded.stageGateContract;$stagePredecessors=@(@(),@('WARP=1'),@('WARP=1','DESTINATION=1'));Eq 'stage count proof' $s.maximumPhysicalActivations 3;Eq 'stage source count' @($s.stages).Count 3;Seq 'stage order proof' @($s.stages|ForEach-Object{$_.name}) @('WARP','DESTINATION','CONFIRM');for($i=0;$i-lt[Math]::Min(3,@($s.stages).Count);$i++){Eq "stage source max[$i]" $s.stages[$i].maxConsumption 1;Seq "stage source predecessor[$i]" $s.stages[$i].requiredPredecessors $stagePredecessors[$i]};Eq 'stage auto' $s.automaticInputBudget 0;Eq 'stage retry' $s.retryBudget 0}
