ming stop' $t.postWarpExpectation.stopAndHandoff $true;Eq 'timing evidence class' $t.postWarpExpectation.evidenceClass 'INFERRED_FROM_HASH_BOUND_STATIC_FLOW_AND_REARM_CONTRACT';Eq 'timing runtime' $t.postWarpExpectation.runtimeObserved $false;Seq 'timing allowed claims' $t.claimCeiling.allowed @('STATIC_STAGE_ORDER','STATIC_MVB01_SEND_BOUNDARY','EXPECTED_POST_WARP_ZERO_MVB01');Seq 'timing forbidden claims' $t.claimCeiling.forbidden @('RUNTIME_OBSERVED','MVB01_ACCEPTED_HIT','OUTBOUND_0X0B01','FULL_MOVEMENT','PLAYER_VISIBLE_MOVEMENT');foreach($property in $t.operations.PSObject.Properties){Eq "timing operation $($property.Name)" $property.Value 0}
 }
