 if($loaded.ContainsKey('movementBreakpointLedger')){$m=$loaded.movementBreakpointLedger;$a=@($m.anchors|Where-Object{$_.id-eq'MVB01_HANDLER_CALLBACK'});Eq 'MVB01 source count' $a.Count 1;if($a.Count-eq1){Eq 'MVB01 source role' $a[0].role 'WARP_SEND_CALLBACK_ENTRY';if(@($a[0].capture)-notcontains'fresh active-flow child[3] equality'){Add-Error 'MVB01 child[3] capture proof missing'}};Eq 'movement runtime source' $m.status.runtimeObserved 'UNSEEN'}
